@Component("customer-subscriber")
public class CustomerSubscriber extends BaseSubscriber {

	public CustomerSubscriber() {
	}
	
    public SubscriptionQueryResult<List<Customer>, Customer> customerSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllCustomerQuery(), 
                		ResponseTypes.multipleInstancesOf(Customer.class),
                		ResponseTypes.instanceOf(Customer.class));
    }

    public SubscriptionQueryResult<Customer, Customer> customerSubscribe(@DestinationVariable UUID customerId) {
        return queryGateway
                .subscriptionQuery(new FindCustomerQuery(new LoadCustomerFilter(customerId)), 
                		ResponseTypes.instanceOf(Customer.class),
                		ResponseTypes.instanceOf(Customer.class));
    }





}

